import math
import mmh3
import time
from typing import Dict, List, Optional, Tuple


class WindowedHyperLogLog:
    """Memory-efficient windowed HyperLogLog cardinality estimator using a 1KB bytearray
    of 8-bit registers and a time-decaying sliding window for distributed peer reachability."""

    def __init__(self, num_registers: int = 1024, window_seconds: float = 300.0) -> None:
        self.num_registers = num_registers
        self.window_seconds = window_seconds
        self.registers = bytearray(num_registers)
        self.timestamps = [0.0] * num_registers
        self._alpha = self._compute_alpha(num_registers)

    def _compute_alpha(self, m: int) -> float:
        if m == 16:
            return 0.673
        elif m == 32:
            return 0.697
        elif m == 64:
            return 0.709
        else:
            return 0.7213 / (1.0 + 1.079 / float(m))

    def _hash(self, item: str) -> int:
        return mmh3.hash64(item, signed=False)[0]

    def add(self, peer_id: str, current_time: Optional[float] = None) -> None:
        now = current_time if current_time is not None else time.time()
        self.expire(now)
        h = self._hash(peer_id)
        idx = h & (self.num_registers - 1)
        remaining = h >> math.log2(self.num_registers)
        rho = self._rho(int(remaining))
        if rho > self.registers[idx] or now >= self.timestamps[idx] + self.window_seconds:
            self.registers[idx] = max(self.registers[idx], rho)
            self.timestamps[idx] = now

    def _rho(self, val: int) -> int:
        if val == 0:
            return 64
        return min(64, (val & -val).bit_length())

    def expire(self, current_time: Optional[float] = None) -> None:
        now = current_time if current_time is not None else time.time()
        for i in range(self.num_registers):
            if self.timestamps[i] > 0 and (now - self.timestamps[i]) > self.window_seconds:
                self.registers[i] = 0
                self.timestamps[i] = 0.0

    def estimate(self, current_time: Optional[float] = None) -> int:
        now = current_time if current_time is not None else time.time()
        self.expire(now)
        m = float(self.num_registers)
        raw_sum = sum(2.0 ** (-r) for r in self.registers)
        if raw_sum == 0.0:
            return 0
        estimate = self._alpha * (m ** 2) / raw_sum
        if estimate <= 2.5 * m:
            zeros = self.registers.count(0)
            if zeros > 0:
                estimate = m * math.log(m / zeros)
        return int(round(estimate))

    def merge(self, other: 'WindowedHyperLogLog', current_time: Optional[float] = None) -> None:
        now = current_time if current_time is not None else time.time()
        self.expire(now)
        other.expire(now)
        for i in range(self.num_registers):
            if other.registers[i] > self.registers[i]:
                self.registers[i] = other.registers[i]
                self.timestamps[i] = other.timestamps[i]
            elif other.registers[i] == self.registers[i] and other.timestamps[i] > self.timestamps[i]:
                self.timestamps[i] = other.timestamps[i]
